contract WedIndexAuthorizationTest is Test {
    WedIndex wedIndex;
    address owner = address(0x01);
    address validNewOwner = address(0x02);
    address stranger = address(0x03);
    address zeroAddress = address(0);

    function setUp() public {
        vm.prank(owner);
        wedIndex = new WedIndex();
    }

    function testVulnerableChangeOwnerToZero() public {
        // Owner can set newOwner to zero without validation
        vm.prank(owner);
        wedIndex.changeOwner(zeroAddress);

        // Verify acceptance makes contract ownerless
        vm.prank(zeroAddress);
        wedIndex.acceptOwnership();

        // Confirm contract became ownerless
        assertEq(wedIndex.owner(), zeroAddress, "Contract should become ownerless");
    }

    function testStrangerCannotAcceptOwnership() public {
        // Set up legitimate owner transfer
        vm.prank(owner);
        wedIndex.changeOwner(validNewOwner);

        // Verify stranger call doesn't change ownership
        vm.prank(stranger);
        wedIndex.acceptOwnership();
        assertEq(wedIndex.owner(), owner, "Original owner should remain");

        // Valid new owner can still claim ownership
        vm.prank(validNewOwner);
        wedIndex.acceptOwnership();
        assertEq(wedIndex.owner(), validNewOwner, "Valid owner should claim ownership");
    }
}
